#include "stdafx.h"#include "HcdElementBase.h"#include <time.h>struct SRTC_P{#include "PrivateVars/RTC.h"};class KRTC : public KHcdElementBase  , protected SRTC_P{public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _RTC("RTC", KRTC::Create);IHcdElement *KRTC::Create(){  return new KRTC;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KRTC, 8 )void KRTC::InitParm(){#include "PrivateVars/RTC.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KRTC::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;}void KRTC::StepCalc( SStepCalcParams &params ){  tm T;  if( _localtime64_s( &T, &params.modelTime ) )    return;  SECONDS = T.tm_sec;  MINUTES = T.tm_min;  HOURS = T.tm_hour;  DAYOFWEEK = T.tm_wday;  DAYOFMONTH = T.tm_mday;  DAYOFYEAR = T.tm_yday;  MONTH = T.tm_mon + 1;  YEAR = T.tm_year + 1900;}